// ==UserScript==
// @name         PolyTrack TAS (frame-exact, track menu)
// @match        https://app-polytrack.kodub.com/*
// @run-at       document-start
// @grant        none
// ==/UserScript==
// Generated by tools/build_menu_userscript.py - do not edit.
// A small menu (top right) picks the track. "Start" opens that track and starts the run; the TAS
// then drives the car on exact 1 ms physics frames. With "Off" selected the game plays normally.
(() => {
  const TRACKS = /*TRACKS*/{};
  const ANCHOR = "for(;t.userControls.buffer.length>0&&t.userControls.buffer[0].frame<=t.frames;){";
  const KEY = "tasTrack";
  const load = () => { try { return localStorage.getItem(KEY) || ""; } catch (e) { return ""; } };
  const save = v => { try { localStorage.setItem(KEY, v); } catch (e) {} };
  let selected = load(); if (selected && !TRACKS[selected]) selected = "";
  const workers = [];
  const send = () => workers.forEach(w => w.postMessage({ __tasSel: selected }));

  const RealWorker = window.Worker;
  window.Worker = function (url, opts) {
    const u = new URL(url, location.href);
    if (!/simulation_worker\.bundle\.js$/.test(u.pathname)) return new RealWorker(url, opts);
    const xhr = new XMLHttpRequest();
    xhr.open("GET", u.href, false);
    xhr.send();
    let src = xhr.responseText;
    if (!src.includes(ANCHOR)) {
      console.warn("[TAS] game version changed; worker patch anchor not found");
      return new RealWorker(url, opts);
    }
    const all = {}; for (const k in TRACKS) all[k] = TRACKS[k].s;
    // the selected track's inputs arrive as a {__tasSel} message, caught before the game's handler
    const sel = `self.__tasAll=${JSON.stringify(all)};self.__tas={i:0,s:[]};` +
      `self.addEventListener("message",e=>{if(e.data&&e.data.__tasSel!==undefined){self.__tas={i:0,s:self.__tasAll[e.data.__tasSel]||[]};e.stopImmediatePropagation()}});`;
    const hook = `if(t.frames==0)self.__tas.i=0;if(self.__tas.s.length){const T=self.__tas;t.userControls.buffer.length=0;` +
      `while(T.i<T.s.length&&T.s[T.i][0]<=t.frames){t.userControls[T.s[T.i][1]]=T.s[T.i][2];T.i++}}`;
    // the worker runs from a blob: URL, so resolve its relative loads against the game's base
    const shim = `(()=>{const B=${JSON.stringify(u.href)},R=x=>typeof x==="string"?new URL(x,B).href:x;` +
      `const o=XMLHttpRequest.prototype.open;XMLHttpRequest.prototype.open=function(m,x,...a){return o.call(this,m,R(x),...a)};` +
      `const f=self.fetch;self.fetch=(x,...a)=>f(R(x),...a);` +
      `const i=self.importScripts;self.importScripts=(...x)=>i(...x.map(R))})();`;
    src = shim + sel + src.replace(ANCHOR, hook + ANCHOR);
    const w = new RealWorker(URL.createObjectURL(new Blob([src], { type: "text/javascript" })), opts);
    workers.push(w); w.postMessage({ __tasSel: selected });
    console.log("[TAS] physics worker patched");
    return w;
  };

  // ---- menu ----
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const visible = el => el && el.offsetParent !== null;
  const button = re => [...document.querySelectorAll("button")].find(b => visible(b) && re.test(b.innerText.trim().replace(/\s+/g, " ")));
  const press = (type) => document.body.dispatchEvent(new KeyboardEvent(type, { key: "w", code: "KeyW", keyCode: 87, which: 87, bubbles: true }));
  async function start(status) {
    if (!selected) { status("pick a track"); return; }
    send();
    const name = TRACKS[selected].name;
    status("opening " + name);
    for (const t of [/^Exit$/, /^Back$/]) { const b = button(t); if (b) { b.click(); await sleep(1500); break; } }
    const tb = button(new RegExp("^" + name + "(\\s|No|\\d|$)"));
    if (!tb) { status("go to the track list first"); return; }
    tb.click(); await sleep(2000);
    const play = button(/^Play$/);
    if (!play) { status("Play button not found"); return; }
    play.click(); await sleep(2000);
    // press W until the race timer runs (the track may still be loading: wait for its timer to appear)
    const timer = () => (document.body.innerText.match(/Current\s*(\d\d:\d\d\.\d{3})/) || [])[1];
    let started = false;
    for (let k = 0; k < 25 && !started; k++) {
      const t = timer();
      if (t && t !== "00:00.000") started = true;
      else if (t) { press("keydown"); await sleep(300); press("keyup"); await sleep(700); }
      else await sleep(1000);
    }
    status(started ? "running " + name : "press W to start");
  }
  function menu() {
    const box = document.createElement("div");
    box.style.cssText = "position:fixed;top:8px;right:8px;z-index:2147483647;background:rgba(20,24,60,.88);color:#fff;" +
      "font:13px sans-serif;padding:6px 8px;border-radius:6px;display:flex;gap:6px;align-items:center";
    const sel = document.createElement("select");
    sel.style.cssText = "font:13px sans-serif";
    sel.add(new Option("TAS off", ""));
    for (const k in TRACKS) sel.add(new Option(`${TRACKS[k].name} (${TRACKS[k].time})`, k));
    sel.value = selected;
    const go = document.createElement("button");
    go.textContent = "Start";
    go.style.cssText = "font:bold 13px sans-serif;cursor:pointer";
    const st = document.createElement("span");
    st.style.cssText = "opacity:.8;max-width:160px";
    const status = s => { st.textContent = s; };
    sel.onchange = () => { selected = sel.value; save(selected); send(); status(selected ? "selected" : "off"); };
    go.onclick = () => start(status);
    // keep the game from treating clicks/keys in the menu as game input
    for (const ev of ["keydown", "keyup", "mousedown", "pointerdown", "touchstart"]) box.addEventListener(ev, e => e.stopPropagation());
    box.append(sel, go, st);
    document.body.appendChild(box);
    window.__tasMenu = { select: v => { sel.value = v; sel.onchange(); }, start: () => start(status) };
  }
  if (document.body) menu(); else document.addEventListener("DOMContentLoaded", menu);
})();
